```java
public class OrderFlow {
    String load(boolean fail) {
        try {
            System.out.println("1: try start");
            if (fail) throw new RuntimeException("boom");
            System.out.println("2: try end");   // skipped if fail
            return "ok";
        } catch (RuntimeException e) {
            System.out.println("3: catch");      // only when fail
            return "recovered";
        } finally {
            System.out.println("4: finally");    // ALWAYS
        }
    }
}
// load(false) prints 1,2,4  -> returns "ok"
// load(true)  prints 1,3,4  -> returns "recovered"
```

